def dijkstra(graph, source):
    dist = {source: 0}
    heap = [(0, source)]

    while heap:
        d, node = heapq.heappop(heap)
        if d > dist.get(node, float('inf')):
            continue

        for neighbor, weight in graph.get(node, []):
            new = d + weight
            if new < dist.get(neighbor, float('inf')):
                dist[neighbor] = new
                heapq.heappush(heap, (new, neighbor))

    return dist
